from src.backend.models.training import Training
from src.backend.schemas.training import TrainingCreate, TrainingUpdate


class TrainingService(BaseCRUDService[Training]):
    """Service for training operations."""

    def __init__(self):
        super().__init__(model=Training)

    def list_trainings_service(
        self,
        db: Session,
        page: int = 1,
        page_size: int = 20,
        q: str | None = None,
    ) -> tuple[list[Training], int, int, int]:
        """List trainings with pagination and search."""
        items, total, page, page_size = self.list_items(db, page, page_size, q)
        return items, total, page, page_size

    def create_training_service(
        self,
        db: Session,
        data: TrainingCreate,
        actor_id: uuid.UUID | None,
    ) -> Training:
        """Create training with audit logging."""
        return self.create_item(
            db,
            data,
            actor_id,
            training_id=data.training_id,
            training_date=data.training_date,
            training_title=data.training_title,
            training_category=data.training_category,
            trainer_name=data.trainer_name,
            trainer_type=data.trainer_type,
            mode=data.mode,
            duration_hours=data.duration_hours,
            participants_count=data.participants_count,
            participant_ids=data.participant_ids,
            department=data.department,
            training_objective=data.training_objective,
            training_status=data.training_status,
            feedback_avg_rating=data.feedback_avg_rating,
            notes=data.notes,
        )

    def get_training_service(self, db: Session, training_id: uuid.UUID) -> Training | None:
        """Get training by ID."""
        return self.get_item(db, training_id)

    def update_training_service(
        self,
        db: Session,
        training_id: uuid.UUID,
        data: TrainingUpdate,
        actor_id: uuid.UUID | None,
    ) -> Training | None:
        """Update training with audit logging."""
        kwargs = {}
        if data.training_id is not None:
            kwargs["training_id"] = data.training_id
        if data.training_date is not None:
            kwargs["training_date"] = data.training_date
        if data.training_title is not None:
            kwargs["training_title"] = data.training_title
        if data.training_category is not None:
            kwargs["training_category"] = data.training_category
        if data.trainer_name is not None:
            kwargs["trainer_name"] = data.trainer_name
        if data.trainer_type is not None:
            kwargs["trainer_type"] = data.trainer_type
        if data.mode is not None:
            kwargs["mode"] = data.mode
        if data.duration_hours is not None:
            kwargs["duration_hours"] = data.duration_hours
        if data.participants_count is not None:
            kwargs["participants_count"] = data.participants_count
        if data.participant_ids is not None:
            kwargs["participant_ids"] = data.participant_ids
        if data.department is not None:
            kwargs["department"] = data.department
        if data.training_objective is not None:
            kwargs["training_objective"] = data.training_objective
        if data.training_status is not None:
            kwargs["training_status"] = data.training_status
        if data.feedback_avg_rating is not None:
            kwargs["feedback_avg_rating"] = data.feedback_avg_rating
        if data.notes is not None:
            kwargs["notes"] = data.notes

        return self.update_item(db, training_id, data, actor_id, **kwargs)

    def soft_delete_training_service(
        self,
        db: Session,
        training_id: uuid.UUID,
        actor_id: uuid.UUID | None,
    ) -> bool:
        """Delete training (soft delete) with audit logging."""
        return self.delete_item(db, training_id, actor_id)

    def _get_entity_type(self) -> str:
        """Get entity type for audit logging."""
        return "training"

    def _get_audit_fields(self, item: Training) -> dict:
        """Get fields for audit logging."""
        return {
            "id": str(item.id),
            "training_id": item.training_id,
            "training_date": str(item.training_date),
            "training_title": item.training_title,
        }


training_service = TrainingService()

